/**
 * @module O 内容工具箱
 *
 * config.runtime 投影器——把 Resource Graph 中的 config.runtime 节点投影回
 * oblivions/gamedata/obl_config.php 的 PHP 数组形态。
 *
 * 设计意图（执行案 06-P5 §4.3.2）：
 * - P5-2 改用 generatePhpFile API：文件头注入 `// AUTO-GENERATED FROM ...` 注释、
 *   模块标签与 sectionTitle 由 schema.projectionTargets 派生，不再使用硬编码文件头。
 * - config.runtime 是单一节点（id='obl_config'），node.data.entries 是 kv-list
 *   形态的 obl_config 字典（23 顶层项）。投影器从 node.data.entries 取出字典，
 *   直接交给 generatePhpFile 输出 `return [...]` 形态。
 * - 字段顺序按节点 data.entries 的 key 插入顺序保留——TS 对象保留 string key 顺序，
 *   loader 从 obl_config.php 解析时按文件顺序写入，投影时按图顺序输出。
 *
 * 字段映射：
 *   - 节点 data.entries         → 顶层 PHP 字典（key 是配置项名，value 是 number /
 *                                  string / boolean / 嵌套数组）
 *
 * 边界：
 * - 节点 data 为 null/非对象时返回空文件骨架（return [];）
 * - 节点 data.entries 缺失时退化为空字典（return [];）
 * - undefined 字段递归移除（与 php-adapter.stripUndefinedFields 对齐）
 * - 保留所有显式值（含 false / 0 / '' / null），保证 round-trip 一致性
 *
 * 集成：
 * - php-adapter.serializePhpResource 路由到本投影器（当 kind='config.runtime' 时）
 * - BuildView 在发布前通过 serializeNodes 间接调用本投影器生成 PublishableFile
 */

import { generatePhpFile, type PhpValue } from '../../shared/serializer/php-codegen';
import type { ResourceNode } from '../../graph/types';
import type { SerializedPhpFile } from '../../adapters/php-adapter';

/** 目标文件路径（工作区相对路径） */
const OBL_CONFIG_FILE_PATH = 'oblivions/gamedata/obl_config.php';

/** 作者资源 YAML 路径——用于 AUTO-GENERATED 注释 */
const OBL_CONFIG_AUTHOR_SOURCE = 'oblivions/content/runtime-config/obl-config.yaml';

/** config.runtime 节点 data 期望形态（与 config-runtime.ts schema fields 对齐） */
interface ConfigRuntimeData {
  entries?: Record<string, unknown>;
  [key: string]: unknown;
}

/**
 * 把 config.runtime 节点投影回 obl_config.php 形态。
 *
 * @param nodes config.runtime 节点数组（期望单个节点，id='obl_config'）
 * @returns 单个 SerializedPhpFile（filePath 指向 oblivions/gamedata/obl_config.php）
 */
export function projectOblConfig(nodes: ResourceNode[]): SerializedPhpFile[] {
  const dict = buildOblConfigDict(nodes);
  const content = generatePhpFile(dict, {
    module: 'C 核心运行时',
    sectionTitle: 'Oblivions 运行时配置',
    autoGeneratedFrom: OBL_CONFIG_AUTHOR_SOURCE,
  });
  return [{ filePath: OBL_CONFIG_FILE_PATH, content }];
}

/**
 * 把 config.runtime 节点重建为 obl_config.php 字典形态。
 *
 * 单一节点（id='obl_config'）的 data.entries 是 kv-list 字典——直接取出交给
 * generatePhpFile。若多个节点存在（异常情况），合并所有 entries。
 */
function buildOblConfigDict(nodes: ResourceNode[]): PhpValue {
  const dict: Record<string, PhpValue> = {};
  for (const node of nodes) {
    if (node.data === null || typeof node.data !== 'object' || Array.isArray(node.data)) {
      continue;
    }
    const data = node.data as ConfigRuntimeData;
    if (data.entries === undefined || data.entries === null) continue;
    const cleaned = stripUndefinedFields(data.entries) as Record<string, PhpValue>;
    for (const [k, v] of Object.entries(cleaned)) {
      dict[k] = v;
    }
  }
  return dict;
}

/**
 * 递归移除 undefined 字段——与 php-adapter.stripUndefinedFields 行为一致。
 *
 * 保留所有显式值（含 false / 0 / '' / null），仅移除 undefined。
 */
function stripUndefinedFields(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(stripUndefinedFields);
  }
  if (value !== null && typeof value === 'object') {
    const result: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      if (v === undefined) continue;
      result[k] = stripUndefinedFields(v);
    }
    return result;
  }
  return value;
}
